import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"What is Codemark?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),i={name:"guide/introduction.md"};function n(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="what-is-codemark" tabindex="-1">What is Codemark? <a class="header-anchor" href="#what-is-codemark" aria-label="Permalink to &quot;What is Codemark?&quot;">​</a></h1><p>Codemark is a CLI and Terminal User Interface (TUI) tool designed to help developers and AI agents navigate and share context within codebases.</p><h2 id="the-vision" tabindex="-1">The Vision <a class="header-anchor" href="#the-vision" aria-label="Permalink to &quot;The Vision&quot;">​</a></h2><p>While AI is transforming how we write code, spending time in the editor is still necessary. However, relying purely on raw text search or brittle line-number bookmarks doesn&#39;t scale. Codemark provides a way to encode semantic meaning into your bookmarks so queries make sense to both humans and agents.</p><h2 id="why-codemark" tabindex="-1">Why Codemark? <a class="header-anchor" href="#why-codemark" aria-label="Permalink to &quot;Why Codemark?&quot;">​</a></h2><ul><li><strong>Semantic Encoding:</strong> Queries make sense to humans (unlike vectors).</li><li><strong>Durable:</strong> Powered by tree-sitter, bookmarks attach to AST nodes, not just line numbers.</li><li><strong>Distill Discoveries:</strong> Save what your AI agents find for future reference.</li><li><strong>Share Context:</strong> Provide high-level, accurate context back to agents.</li></ul><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Fast Text Search (FTS) &amp; Semantic Search</strong></li><li><strong>Bookmark Metadata:</strong> Links, notes, comments, health status.</li><li><strong>Keyboard-Driven TUI:</strong> Lazygit-inspired, with Vim motions and mouse support.</li><li><strong>Multi-Repo Queries</strong> &amp; Automatic repository detection.</li><li><strong>Agent Skill Integration</strong></li><li><strong>Highly Configurable:</strong> Editor integration and multiple themes.</li></ul>',8)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
